	["@src/utility/librarys/components/slider"] = function()


return function(Library, context)
	local InputService = context.InputService
	local Mouse = context.Mouse
	local RenderStepped = context.RenderStepped
	local TweenService = game:GetService('TweenService')

	local Component = {}

	local function createRounder(rounding)
		return function(value)
			if rounding == 0 then
				return math.floor(value)
			end
			return tonumber(string.format('%.' .. tostring(rounding) .. 'f', value))
		end
	end

	local function createSizeTweener()
		local activeTween

		return function(frame, size)
			if frame.Size == size then
				return
			end

			if activeTween then
				activeTween:Cancel()
				activeTween = nil
			end

			local tween = TweenService:Create(frame, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
				Size = size;
			}) 
			activeTween = tween
			tween.Completed:Connect(function()
				if activeTween == tween then
					activeTween = nil
				end
			end)
			tween:Play()
		end
	end

	function Component.AddSlider(self, Idx, Info)
		assert(Info.Default ~= nil, 'AddSlider: Missing default value.')
		assert(Info.Text,    'AddSlider: Missing slider text.')
		assert(Info.Min ~= nil,     'AddSlider: Missing minimum value.')
		assert(Info.Max ~= nil,     'AddSlider: Missing maximum value.')
		assert(Info.Rounding ~= nil, 'AddSlider: Missing rounding value.')

		local Slider = {
			Value    = Info.Default;
			Min      = Info.Min;
			Max      = Info.Max;
			Rounding = Info.Rounding;
			MaxSize  = 232;
			Type     = 'Slider';

			Text     = Info.Text;
			Prefix   = type(Info.Prefix) == "string" and Info.Prefix or "";
			Suffix   = type(Info.Suffix) == "string" and Info.Suffix or "";

			Visible  = (type(Info.Visible)  == "boolean") and Info.Visible  or true;
			Disabled = (type(Info.Disabled) == "boolean") and Info.Disabled or false;

			Callback = Info.Callback or function(_) end;
			Changed  = Info.Changed  or function(_) end;
			Compact  = not not Info.Compact;
			HideMax  = not not Info.HideMax;
			Tooltip  = Info.Tooltip;
		}

		if self.Objects then
			table.insert(self.Objects, {
				internal_name = Idx, settings = Info, Type = "Slider"
			})
		end

		local Groupbox  = self
		local Container = Groupbox.Container

		local SliderHeader = Library:Create('Frame', {
			BackgroundTransparency = 1;
			Size = UDim2.new(1, -4, 0, 14);
			Visible = Slider.Visible;
			ZIndex = 5;
			Parent = Container;
		})
		local SliderTitle = Library:CreateLabel({
			Size = UDim2.new(0.6, 0, 1, 0);
			TextSize = 14;
			Text = Slider.Text;
			TextXAlignment = Enum.TextXAlignment.Left;
			ZIndex = 6;
			Parent = SliderHeader;
		})
		local DisplayLabel = Library:CreateLabel({
			Position = UDim2.new(0.6, 0, 0, 0);
			Size = UDim2.new(0.4, 0, 1, 0);
			TextSize = 14;
			Text = '';
			TextXAlignment = Enum.TextXAlignment.Right;
			ZIndex = 6;
			Parent = SliderHeader;
		})
		Groupbox:AddBlank(3, Slider.Visible)

		local SliderOuter = Library:Create('Frame', {
			BackgroundTransparency = 1;
			BorderSizePixel = 0;
			Size = UDim2.new(1, -4, 0, 18);
			Visible = Slider.Visible;
			Active = true;
			ZIndex = 5;
			Parent = Container;
		})

		Library:RegisterSearchEntry(Groupbox, {
			Kind = 'Slider';
			Text = Slider.Text;
			Target = SliderOuter;
		})

		SliderOuter:GetPropertyChangedSignal('AbsoluteSize'):Connect(function()
			Slider.MaxSize = math.max(0, math.floor(SliderOuter.AbsoluteSize.X / Library:GetUIScale() + 0.5) - 2)
		end)

		Library:AddToRegistry(SliderOuter, { BorderColor3 = 'Black' })

		local SliderInner = Library:Create('Frame', {
			BackgroundColor3 = Library.MainColor;
			BorderColor3 = Library.OutlineColor;
			BorderMode = Enum.BorderMode.Inset;
			Position = UDim2.new(0, 0, 0, 7);
			Size = UDim2.new(1, 0, 0, 4);
			ZIndex = 6;
			Parent = SliderOuter;
		})
		Library:Create('UICorner', { CornerRadius = UDim.new(0, 0); Parent = SliderInner })
		local SliderGlow = Library:Create('Frame', {
			BackgroundTransparency = 1;
			BorderSizePixel = 0;
			Position = UDim2.new(0, 0, 0, 7);
			Size = UDim2.new(1, 0, 0, 4);
			ZIndex = 10;
			Parent = SliderOuter;
		})
		local setSliderGlow = Library:AddAccentGlow(SliderGlow, false, false, 0.55)
		SliderOuter.MouseEnter:Connect(function()
			setSliderGlow(true)
		end)
		SliderOuter.MouseLeave:Connect(function()
			setSliderGlow(false)
		end)

		Library:AddToRegistry(SliderInner, {
			BackgroundColor3 = 'MainColor';
			BorderColor3 = 'OutlineColor';
		})

		local Fill = Library:Create('Frame', {
			BackgroundColor3 = Library.AccentColor;
			BorderSizePixel = 0;
			Size = UDim2.new(0, 0, 1, 0);
			ZIndex = 7;
			Parent = SliderInner;
		})
		Library:Create('UICorner', { CornerRadius = UDim.new(0, 0); Parent = Fill })

		Library:AddToRegistry(Fill, {
			BackgroundColor3 = 'AccentColor';
			BorderColor3 = 'AccentColorDark';
		})

		local HideBorderRight = Library:Create('Frame', {
			BackgroundColor3 = Library.AccentColor;
			BorderSizePixel = 0;
			Position = UDim2.new(1, 0, 0, 0);
			Size = UDim2.new(0, 1, 1, 0);
			ZIndex = 8;
			Parent = Fill;
		})

		Library:AddToRegistry(HideBorderRight, { BackgroundColor3 = 'AccentColor' })
		local FillHandle = Library:Create('Frame', {
			AnchorPoint = Vector2.new(0.5, 0.5);
			BackgroundColor3 = Library.FontColor;
			BorderColor3 = Library.AccentColorDark;
			Position = UDim2.new(0, 0, 0.5, 0);
			Size = UDim2.fromOffset(10, 10);
			Visible = false;
			ZIndex = 9;
			Parent = SliderInner;
		})
		Library:Create('UICorner', { CornerRadius = UDim.new(0, 0); Parent = FillHandle })
		Library:AddToRegistry(FillHandle, {
			BackgroundColor3 = 'FontColor';
			BorderColor3 = 'AccentColorDark';
		})

		local ValueBox = Library:Create('TextBox', {
			BackgroundTransparency = 1;
			BorderSizePixel = 0;
			ClearTextOnFocus = false;
			FontFace = Library.Font;
			Position = UDim2.new(0.6, 0, 0, 0);
			PlaceholderText = '';
			Size = UDim2.new(0.4, 0, 1, 0);
			Text = '';
			TextColor3 = Library.FontColor;
			TextSize = 14;
			TextStrokeTransparency = 0;
			TextXAlignment = Enum.TextXAlignment.Right;
			TextYAlignment = Enum.TextYAlignment.Center;
			Visible = false;
			ZIndex = 10;
			Parent = SliderHeader;
		})

		Library:AddToRegistry(ValueBox, { TextColor3 = 'FontColor' })

		local IsTypingValue = false
		local UpdateDisplay
		local ApplyValue
		local TweenFillSize = createSizeTweener()

		local Round = createRounder(Slider.Rounding)

		local function FinishTyping(commit)
			if not IsTypingValue then return end
			IsTypingValue = false
			ValueBox.Visible = false
			DisplayLabel.Visible = true

			if commit then
				local typedValue = tonumber(ValueBox.Text)
				if typedValue then
					ApplyValue(typedValue)
				else
					UpdateDisplay()
				end
			else
				UpdateDisplay()
			end

			Library:AttemptSave()
		end

		local function BeginTyping()
			if Slider.Disabled or IsTypingValue then return end
			IsTypingValue = true
			ValueBox.Text = tostring(Slider.Value)
			ValueBox.Visible = true
			DisplayLabel.Visible = false
			pcall(function()
				ValueBox:CaptureFocus()
				ValueBox.CursorPosition = #ValueBox.Text + 1
			end)
		end

		ValueBox.FocusLost:Connect(function(enterPressed)
			FinishTyping(enterPressed)
		end)

		UpdateDisplay = function()
			local left = (Slider.Prefix or "")
			local right = (Slider.Suffix or "")

			local value = tostring(Round(Slider.Value))
			if not IsTypingValue then
				if Slider.HideMax then
					DisplayLabel.Text = string.format('%s%s', value, right)
				else
					DisplayLabel.Text = string.format('%s%s/%s%s', left, value, tostring(Slider.Max), right)
				end
			else
				ValueBox.Text = tostring(Slider.Value)
			end

			local X = math.ceil(Library:MapValue(Slider.Value, Slider.Min, Slider.Max, 0, Slider.MaxSize))
			
			TweenFillSize(Fill, UDim2.new(0, X, 1, 0))
			FillHandle.Position = UDim2.new(0, X, 0.5, 0)
			HideBorderRight.Visible = not (X == Slider.MaxSize or X == 0)

			SliderHeader.Visible = Slider.Visible
			SliderInner.Visible = Slider.Visible
			SliderOuter.Visible = Slider.Visible
			DisplayLabel.Visible = Slider.Visible and not IsTypingValue
			ValueBox.Visible = Slider.Visible and IsTypingValue
		end

		ApplyValue = function(numOrStr)
			local Num = tonumber(numOrStr)
			if not Num then return end
			Num = math.clamp(Num, Slider.Min, Slider.Max)
			local old = Slider.Value
			Slider.Value = Num
			UpdateDisplay()
			if not Slider.Disabled and Num ~= old then
				Library:SafeCallback(Slider.Callback, Slider.Value)
				Library:SafeCallback(Slider.Changed, Slider.Value)
			end
		end

		Library:OnHighlight(SliderOuter, SliderOuter,
			{ BorderColor3 = 'AccentColor' },
			{ BorderColor3 = 'Black' }
		)

		if type(Slider.Tooltip) == 'string' then
			Library:AddToolTip(Slider.Tooltip, SliderOuter)
		end

		function Slider:UpdateColors()
			Fill.BackgroundColor3 = Library.AccentColor
			Fill.BorderColor3     = Library.AccentColorDark
			local disabledTransparency = Slider.Disabled and 0.45 or 0
			SliderInner.BackgroundTransparency = disabledTransparency
			Fill.BackgroundTransparency = disabledTransparency
			FillHandle.BackgroundTransparency = Slider.Disabled and 0.35 or 0
		end

		function Slider:GetValueFromXScale(scale)
			return Round(Library:MapValue(scale, 0, 1, Slider.Min, Slider.Max))
		end

		function Slider:GetValueFromXOffset(px)
			return Round(Library:MapValue(px, 0, Slider.MaxSize, Slider.Min, Slider.Max))
		end

		function Slider:Display()
			UpdateDisplay()
		end

		function Slider:SetValue(numOrStr)
			ApplyValue(numOrStr)
		end

		function Slider:SetText(t) if type(t) == "string" then Slider.Text = t; SliderTitle.Text = t; Slider:Display() end end
		function Slider:SetPrefix(p) if type(p) == "string" then Slider.Prefix = p; Slider:Display() end end
		function Slider:SetSuffix(s) if type(s) == "string" then Slider.Suffix = s; Slider:Display() end end
		function Slider:SetVisible(v) Slider.Visible = not not v; Slider:Display(); Groupbox:Resize() end
		function Slider:SetDisabled(d) Slider.Disabled = not not d; Slider:UpdateColors() end

		function Slider:OnChanged(Func)
			Slider.Changed = Func
			pcall(Func, Slider.Value)
		end

		SliderOuter.InputBegan:Connect(function(Input)
			if Slider.Disabled then return end
			if Input.UserInputType == Enum.UserInputType.MouseButton2 and not Library:MouseIsOverOpenedFrame() then
				BeginTyping()
			elseif Input.UserInputType == Enum.UserInputType.MouseButton1 and not Library:MouseIsOverOpenedFrame() and not IsTypingValue then
				local FillStartX = Fill.AbsolutePosition.X

				while InputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) do
					local nX = math.clamp((Mouse.X - FillStartX) / Library:GetUIScale(), 0, Slider.MaxSize)
					local nValue = Slider:GetValueFromXOffset(nX)
					local old = Slider.Value
					Slider.Value = nValue

					Slider:Display()

					if nValue ~= old then
						Library:SafeCallback(Slider.Callback, Slider.Value)
						Library:SafeCallback(Slider.Changed, Slider.Value)
					end

					RenderStepped:Wait()
				end

				Library:AttemptSave()
			end
		end)

		Slider:UpdateColors()
		Slider:Display()
		Groupbox:AddBlank(Info.BlankSize or 6)
		Groupbox:Resize()

		aztup_options[Idx] = Slider
		Library:UpdateDependencyBoxes()
		return Slider
	end

	function Component.AddMinMaxSlider(self, Idx, Info)
		assert(Info.Text, 'AddMinMaxSlider: Missing slider text.')
		assert(Info.Min ~= nil, 'AddMinMaxSlider: Missing minimum value.')
		assert(Info.Max ~= nil, 'AddMinMaxSlider: Missing maximum value.')
		assert(Info.Rounding ~= nil, 'AddMinMaxSlider: Missing rounding value.')

		local defaultMin, defaultMax
		if type(Info.Default) == 'table' then
			defaultMin = Info.Default.Min or Info.Default[1]
			defaultMax = Info.Default.Max or Info.Default[2]
		end
		if defaultMin == nil then
			defaultMin = Info.DefaultMin
		end
		if defaultMax == nil then
			defaultMax = Info.DefaultMax
		end

		local minVal = tonumber(defaultMin) or Info.Min
		local maxVal = tonumber(defaultMax) or Info.Max

		minVal = math.clamp(minVal, Info.Min, Info.Max)
		maxVal = math.clamp(maxVal, Info.Min, Info.Max)
		if minVal > maxVal then
			minVal, maxVal = maxVal, minVal
		end

		local rangeValue = {
			Min = minVal;
			Max = maxVal;
		}

		local MinMaxSlider = {
			Value = rangeValue;
			Min = Info.Min;
			Max = Info.Max;
			Rounding = Info.Rounding;
			MaxSize = 232;
			Type = 'MinMaxSlider';

			Text = Info.Text;
			Prefix = type(Info.Prefix) == "string" and Info.Prefix or "";
			Suffix = type(Info.Suffix) == "string" and Info.Suffix or "";

			Visible = (type(Info.Visible) == "boolean") and Info.Visible or true;
			Disabled = (type(Info.Disabled) == "boolean") and Info.Disabled or false;

			Callback = Info.Callback or function(_) end;
			Changed = Info.Changed or function(_) end;
			Compact = not not Info.Compact;
			Tooltip = Info.Tooltip;
		}

		local Groupbox = self
		local Container = Groupbox.Container

		local SliderHeader = Library:Create('Frame', {
			BackgroundTransparency = 1;
			Size = UDim2.new(1, -4, 0, 14);
			Visible = MinMaxSlider.Visible;
			ZIndex = 5;
			Parent = Container;
		})
		local SliderTitle = Library:CreateLabel({
			Size = UDim2.new(0.6, 0, 1, 0);
			TextSize = 14;
			Text = MinMaxSlider.Text;
			TextXAlignment = Enum.TextXAlignment.Left;
			ZIndex = 6;
			Parent = SliderHeader;
		})
		local DisplayLabel = Library:CreateLabel({
			Position = UDim2.new(0.6, 0, 0, 0);
			Size = UDim2.new(0.4, 0, 1, 0);
			TextSize = 14;
			Text = '';
			TextXAlignment = Enum.TextXAlignment.Right;
			ZIndex = 6;
			Parent = SliderHeader;
		})
		Groupbox:AddBlank(3, MinMaxSlider.Visible)

		local SliderOuter = Library:Create('Frame', {
			BackgroundTransparency = 1;
			BorderSizePixel = 0;
			Size = UDim2.new(1, -4, 0, 18);
			Visible = MinMaxSlider.Visible;
			Active = true;
			ZIndex = 5;
			Parent = Container;
		})

		Library:RegisterSearchEntry(Groupbox, {
			Kind = 'MinMaxSlider';
			Text = MinMaxSlider.Text;
			Target = SliderOuter;
		})

		SliderOuter:GetPropertyChangedSignal('AbsoluteSize'):Connect(function()
			MinMaxSlider.MaxSize = math.max(0, math.floor(SliderOuter.AbsoluteSize.X / Library:GetUIScale() + 0.5) - 2)
		end)

		Library:AddToRegistry(SliderOuter, { BorderColor3 = 'Black' })

		local SliderInner = Library:Create('Frame', {
			BackgroundColor3 = Library.MainColor;
			BorderColor3 = Library.OutlineColor;
			BorderMode = Enum.BorderMode.Inset;
			Position = UDim2.new(0, 0, 0, 7);
			Size = UDim2.new(1, 0, 0, 6);
			ZIndex = 6;
			Parent = SliderOuter;
		})
		Library:Create('UICorner', { CornerRadius = UDim.new(0, 0); Parent = SliderInner })
		local SliderGlow = Library:Create('Frame', {
			BackgroundTransparency = 1;
			BorderSizePixel = 0;
			Position = UDim2.new(0, 0, 0, 7);
			Size = UDim2.new(1, 0, 0, 6);
			ZIndex = 10;
			Parent = SliderOuter;
		})
		local setSliderGlow = Library:AddAccentGlow(SliderGlow, false, false, 0.55)
		SliderOuter.MouseEnter:Connect(function()
			setSliderGlow(true)
		end)
		SliderOuter.MouseLeave:Connect(function()
			setSliderGlow(false)
		end)

		Library:AddToRegistry(SliderInner, {
			BackgroundColor3 = 'MainColor';
			BorderColor3 = 'OutlineColor';
		})

		local RangeFill = Library:Create('Frame', {
			BackgroundColor3 = Library.AccentColor;
			BorderSizePixel = 0;
			Size = UDim2.new(0, 0, 1, 0);
			ZIndex = 7;
			Parent = SliderInner;
		})
		Library:Create('UICorner', { CornerRadius = UDim.new(0, 0); Parent = RangeFill })

		Library:AddToRegistry(RangeFill, {
			BackgroundColor3 = 'AccentColor';
			BorderColor3 = 'AccentColorDark';
		})

		local HideBorderLeft = Library:Create('Frame', {
			BackgroundColor3 = Library.AccentColor;
			BorderSizePixel = 0;
			Position = UDim2.new(0, 0, 0, 0);
			Size = UDim2.new(0, 1, 1, 0);
			ZIndex = 8;
			Parent = RangeFill;
		})

		local HideBorderRight = Library:Create('Frame', {
			BackgroundColor3 = Library.AccentColor;
			BorderSizePixel = 0;
			Position = UDim2.new(1, 0, 0, 0);
			Size = UDim2.new(0, 1, 1, 0);
			ZIndex = 8;
			Parent = RangeFill;
		})

		Library:AddToRegistry(HideBorderLeft, { BackgroundColor3 = 'AccentColor' })
		Library:AddToRegistry(HideBorderRight, { BackgroundColor3 = 'AccentColor' })

		local MinHandle = Library:Create('Frame', {
			BackgroundColor3 = Library.FontColor;
			BorderColor3 = Library.AccentColorDark;
			AnchorPoint = Vector2.new(0.5, 0.5);
			Position = UDim2.new(0, 0, 0.5, 0);
			Size = UDim2.fromOffset(10, 10);
			Visible = false;
			ZIndex = 9;
			Parent = SliderInner;
		})
		Library:Create('UICorner', { CornerRadius = UDim.new(0, 0); Parent = MinHandle })

		local MaxHandle = Library:Create('Frame', {
			BackgroundColor3 = Library.FontColor;
			BorderColor3 = Library.AccentColorDark;
			AnchorPoint = Vector2.new(0.5, 0.5);
			Position = UDim2.new(0, 0, 0.5, 0);
			Size = UDim2.fromOffset(10, 10);
			Visible = false;
			ZIndex = 9;
			Parent = SliderInner;
		})
		Library:Create('UICorner', { CornerRadius = UDim.new(0, 0); Parent = MaxHandle })

		Library:AddToRegistry(MinHandle, {
			BackgroundColor3 = 'FontColor';
			BorderColor3 = 'AccentColorDark';
		})
		Library:AddToRegistry(MaxHandle, {
			BackgroundColor3 = 'FontColor';
			BorderColor3 = 'AccentColorDark';
		})

		Library:OnHighlight(SliderOuter, SliderOuter,
			{ BorderColor3 = 'AccentColor' },
			{ BorderColor3 = 'Black' }
		)

		if type(MinMaxSlider.Tooltip) == 'string' then
			Library:AddToolTip(MinMaxSlider.Tooltip, SliderOuter)
		end

		function MinMaxSlider:UpdateColors()
			RangeFill.BackgroundColor3 = Library.AccentColor
			RangeFill.BorderColor3 = Library.AccentColorDark
			local disabledTransparency = MinMaxSlider.Disabled and 0.45 or 0
			SliderInner.BackgroundTransparency = disabledTransparency
			RangeFill.BackgroundTransparency = disabledTransparency
			MinHandle.BackgroundTransparency = MinMaxSlider.Disabled and 0.35 or 0
			MaxHandle.BackgroundTransparency = MinMaxSlider.Disabled and 0.35 or 0
		end

		local Round = createRounder(MinMaxSlider.Rounding)
		local TweenRangeFillSize = createSizeTweener()

		function MinMaxSlider:GetValueFromXOffset(px)
			return Round(Library:MapValue(px, 0, MinMaxSlider.MaxSize, MinMaxSlider.Min, MinMaxSlider.Max))
		end

		function MinMaxSlider:Display()
			local left = (MinMaxSlider.Prefix or "")
			local right = (MinMaxSlider.Suffix or "")
			local minText = string.format('%s%s%s', left, tostring(MinMaxSlider.Value.Min), right)
			local maxText = string.format('%s%s%s', left, tostring(MinMaxSlider.Value.Max), right)

			DisplayLabel.Text = string.format('%s - %s', minText, maxText)

			local minX = math.ceil(Library:MapValue(MinMaxSlider.Value.Min, MinMaxSlider.Min, MinMaxSlider.Max, 0, MinMaxSlider.MaxSize))
			local maxX = math.ceil(Library:MapValue(MinMaxSlider.Value.Max, MinMaxSlider.Min, MinMaxSlider.Max, 0, MinMaxSlider.MaxSize))

			if maxX < minX then
				minX, maxX = maxX, minX
			end

			local width = math.max(0, maxX - minX)
			RangeFill.Position = UDim2.new(0, minX, 0, 0)
			RangeFill.Size =  UDim2.new(0, width, 1, 0)
			HideBorderLeft.Visible = not (minX == 0 or width == 0)
			HideBorderRight.Visible = not (maxX == MinMaxSlider.MaxSize or width == 0)

			MinHandle.Position = UDim2.new(0, minX, 0.5, 0)
			MaxHandle.Position = UDim2.new(0, maxX, 0.5, 0)

			SliderHeader.Visible = MinMaxSlider.Visible
			SliderInner.Visible = MinMaxSlider.Visible
			SliderOuter.Visible = MinMaxSlider.Visible
		end

		function MinMaxSlider:SetValue(range)
			if type(range) ~= 'table' then return end
			local newMin = tonumber(range.Min or range[1])
			local newMax = tonumber(range.Max or range[2])
			if not newMin or not newMax then return end
			newMin = math.clamp(newMin, MinMaxSlider.Min, MinMaxSlider.Max)
			newMax = math.clamp(newMax, MinMaxSlider.Min, MinMaxSlider.Max)
			if newMin > newMax then
				newMin, newMax = newMax, newMin
			end
			local oldMin, oldMax = MinMaxSlider.Value.Min, MinMaxSlider.Value.Max
			MinMaxSlider.Value.Min = newMin
			MinMaxSlider.Value.Max = newMax
			MinMaxSlider:Display()
			if not MinMaxSlider.Disabled and (newMin ~= oldMin or newMax ~= oldMax) then
				Library:SafeCallback(MinMaxSlider.Callback, MinMaxSlider.Value)
				Library:SafeCallback(MinMaxSlider.Changed, MinMaxSlider.Value)
			end
		end

		function MinMaxSlider:SetText(t) if type(t) == "string" then MinMaxSlider.Text = t; SliderTitle.Text = t; MinMaxSlider:Display() end end
		function MinMaxSlider:SetPrefix(p) if type(p) == "string" then MinMaxSlider.Prefix = p; MinMaxSlider:Display() end end
		function MinMaxSlider:SetSuffix(s) if type(s) == "string" then MinMaxSlider.Suffix = s; MinMaxSlider:Display() end end
		function MinMaxSlider:SetVisible(v) MinMaxSlider.Visible = not not v; MinMaxSlider:Display(); Groupbox:Resize() end
		function MinMaxSlider:SetDisabled(d) MinMaxSlider.Disabled = not not d; MinMaxSlider:UpdateColors() end

		function MinMaxSlider:OnChanged(Func)
			MinMaxSlider.Changed = Func
			pcall(Func, MinMaxSlider.Value)
		end

		SliderOuter.InputBegan:Connect(function(Input)
			if MinMaxSlider.Disabled then return end
			if Input.UserInputType == Enum.UserInputType.MouseButton1 and not Library:MouseIsOverOpenedFrame() then
				local innerX = SliderInner.AbsolutePosition.X
				local minX = math.ceil(Library:MapValue(MinMaxSlider.Value.Min, MinMaxSlider.Min, MinMaxSlider.Max, 0, MinMaxSlider.MaxSize))
				local maxX = math.ceil(Library:MapValue(MinMaxSlider.Value.Max, MinMaxSlider.Min, MinMaxSlider.Max, 0, MinMaxSlider.MaxSize))
				local mouseX = math.clamp((Mouse.X - innerX) / Library:GetUIScale(), 0, MinMaxSlider.MaxSize)
				local dragTarget = (math.abs(mouseX - minX) <= math.abs(mouseX - maxX)) and 'Min' or 'Max'

				while InputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) do
					local nX = math.clamp((Mouse.X - innerX) / Library:GetUIScale(), 0, MinMaxSlider.MaxSize)
					local nValue = MinMaxSlider:GetValueFromXOffset(nX)
					local oldMin, oldMax = MinMaxSlider.Value.Min, MinMaxSlider.Value.Max

					if dragTarget == 'Min' then
						if nValue > MinMaxSlider.Value.Max then
							MinMaxSlider.Value.Min = MinMaxSlider.Value.Max
							MinMaxSlider.Value.Max = nValue
							dragTarget = 'Max'
						else
							MinMaxSlider.Value.Min = nValue
						end
					else
						if nValue < MinMaxSlider.Value.Min then
							MinMaxSlider.Value.Max = MinMaxSlider.Value.Min
							MinMaxSlider.Value.Min = nValue
							dragTarget = 'Min'
						else
							MinMaxSlider.Value.Max = nValue
						end
					end

					MinMaxSlider:Display()

					if MinMaxSlider.Value.Min ~= oldMin or MinMaxSlider.Value.Max ~= oldMax then
						Library:SafeCallback(MinMaxSlider.Callback, MinMaxSlider.Value)
						Library:SafeCallback(MinMaxSlider.Changed, MinMaxSlider.Value)
					end

					RenderStepped:Wait()
				end

				Library:AttemptSave()
			end
		end)

		MinMaxSlider:UpdateColors()
		MinMaxSlider:Display()
		Groupbox:AddBlank(Info.BlankSize or 6)
		Groupbox:Resize()

		aztup_options[Idx] = MinMaxSlider
		Library:UpdateDependencyBoxes()
		return MinMaxSlider
	end

	return Component
end
	end,
	["@src/utility/librarys/components/toggle"] = function()



local signal = require("@src/utility/signal");
local curr_mode_select;
return function(Library, context)
	local InputService = context.InputService
	local Mouse = context.Mouse
	local RenderStepped = context.RenderStepped
	local BaseAddons = context.BaseAddons

	local Component = {}

	function Component.AddToggle(self, Idx, Info)
		assert(Info.Text, 'AddInput: Missing `Text` string.')
		if self.Objects then
			table.insert(self.Objects, {
				internal_name = Idx, settings = Info
			})
		else
			print(self)
		end;
		
		local Toggle = {
			Value = Info.Default or false;
			Type = 'Toggle';
			Flag = Idx,
			Name = Info.Text,
			TabName = self.Tab and self.Tab.Name,
			ArrayList = Info.ArrayList ~= false,
			
			Callback = Info.Callback or function(Value) end;
			Addons = {};
			Risky = Info.Risky;
		}

		local Groupbox = self;
		local Container = Groupbox.Container;

		local ToggleRow = Library:Create('Frame', {
			BackgroundTransparency = 1;
			Size = UDim2.new(1, -4, 0, 18);
			ZIndex = 5;
			Parent = Container;
		})

		local ToggleLabel = Library:CreateLabel({
			Size = UDim2.new(1, -24, 1, 0);
			Position = UDim2.fromOffset(0, 0);
			TextSize = 14;
			Text = Info.Text;
			TextXAlignment = Enum.TextXAlignment.Left;
			ZIndex = 6;
			Parent = ToggleRow;
		})

		Library:Create('UIListLayout', {
			Padding = UDim.new(0, 4);
			FillDirection = Enum.FillDirection.Horizontal;
			HorizontalAlignment = Enum.HorizontalAlignment.Right;
			SortOrder = Enum.SortOrder.LayoutOrder;
			Parent = ToggleLabel;
		})

		local ToggleOuter = Library:Create('Frame', {
			AnchorPoint = Vector2.new(1, 0.5);
			Position = UDim2.new(1, -2, 0.5, 0);
			Size = UDim2.fromOffset(16, 16);
			BackgroundColor3 = Library.MainColor;
			BorderColor3 = Library.OutlineColor;
			BorderSizePixel = 1;
			Active = true;
			ZIndex = 6;
			Parent = ToggleRow;
		})
		Library:AddToRegistry(ToggleOuter, {
			BackgroundColor3 = 'MainColor';
			BorderColor3 = 'OutlineColor';
		})

		local ToggleMark = Library:CreateLabelNoStroke({
			BackgroundTransparency = 1;
			Size = UDim2.fromScale(1, 1);
			Text = '✓';
			TextColor3 = Library.FontColor;
			TextSize = 13;
			TextXAlignment = Enum.TextXAlignment.Center;
			TextYAlignment = Enum.TextYAlignment.Center;
			Visible = false;
			ZIndex = 8;
			Parent = ToggleOuter;
		})
		ToggleMark.FontFace = Font.fromEnum(Enum.Font.GothamBold)
		local ToggleGlow = Library:Create('Frame', {
			BackgroundTransparency = 1;
			BorderSizePixel = 0;
			Size = UDim2.fromScale(1, 1);
			ZIndex = 7;
			Parent = ToggleOuter;
		})
		local setToggleGlow = Library:AddAccentGlow(ToggleGlow, false, false, 0.55)

		local ToggleRegion = Library:Create('Frame', {
			BackgroundTransparency = 1;
			Size = UDim2.fromScale(1, 1);
			Active = true;
			ZIndex = 9;
			Parent = ToggleOuter;
		})
		ToggleRegion.MouseEnter:Connect(function()
			setToggleGlow(true)
		end)
		ToggleRegion.MouseLeave:Connect(function()
			setToggleGlow(false)
		end)

		Library:OnHighlight(ToggleRegion, ToggleOuter,
			{ BorderColor3 = 'AccentColor' },
			{ BorderColor3 = function()
				return Toggle.Value and Library.AccentColor or Library.OutlineColor
			end }
		)

		function Toggle:UpdateColors()
			Toggle:Display();
		end;

		if type(Info.Tooltip) == 'string' then
			Library:AddToolTip(Info.Tooltip, ToggleRegion)
		end

		function Toggle:Display()
			ToggleRow.BackgroundColor3 = Toggle.Value and Library.AccentColor or Library.MainColor
			ToggleRow.BackgroundTransparency = 1
			ToggleRow.Size = UDim2.new(1, -4, 0, 18)
			ToggleLabel.Size = UDim2.new(1, -24, 1, 0)
			ToggleLabel.TextSize = 14
			ToggleOuter.Visible = true
			ToggleOuter.BackgroundColor3 = Library.MainColor;
			Library.RegistryMap[ToggleOuter].Properties.BackgroundColor3 = 'MainColor';
			ToggleOuter.BorderColor3 = Toggle.Value and Library.AccentColor or Library.OutlineColor;
			Library.RegistryMap[ToggleOuter].Properties.BorderColor3 = Toggle.Value and 'AccentColor' or 'OutlineColor';
			ToggleMark.Visible = Toggle.Value
			Groupbox:Resize()
		end;
		Toggle.Row = ToggleRow
		Toggle.Groupbox = Groupbox
		Toggle.RefreshThemeAppearance = Toggle.Display
		Toggle.__internal = signal.new();

		local function showModuleSettings(input)
			if input.UserInputType ~= Enum.UserInputType.MouseButton2 then
				return
			end
			if Toggle.SettingsPanel then
				Toggle.SettingsPanel:Destroy()
				Toggle.SettingsPanel = nil
			end

			local settings = {}
			local seenSettings = {}
			local function addSetting(flag, metadata)
				local option = aztup_options[flag]
				if not option or not option.Type or seenSettings[flag] then
					return
				end
				seenSettings[flag] = true
				local value = option.Value
				local displayValue
				if typeof(value) == "Color3" then
					displayValue = string.format("#%02X%02X%02X",
						math.floor(value.R * 255 + 0.5),
						math.floor(value.G * 255 + 0.5),
						math.floor(value.B * 255 + 0.5)
					)
				elseif type(value) == "table" then
					local values = {}
					for key, selected in pairs(value) do
						if selected then
							table.insert(values, tostring(key))
						end
					end
					table.sort(values)
					displayValue = #values > 0 and table.concat(values, ", ") or "none"
				else
					displayValue = tostring(value)
				end
				table.insert(settings, {
					Name = option.Name or option.Text or option.Title or (metadata and metadata.Text) or flag,
					Value = displayValue,
				})
			end

			for _, flag in ipairs(Info.SettingsFlags or {}) do
				addSetting(flag)
			end

			local foundToggle = false
			for _, object in ipairs(Groupbox.Objects or {}) do
				if object.internal_name == Idx then
					foundToggle = true
				elseif foundToggle then
					local option = aztup_options[object.internal_name]
					if option and option.Type == "Toggle" then
						break
					end
					addSetting(object.internal_name, object.settings)
				end
			end

			local rowHeight = 18
			local visibleCount = math.min(#settings, 12)
			local extraRowCount = #settings > visibleCount and 1 or 0
			local panelHeight = 32 + math.max(1, visibleCount + extraRowCount) * rowHeight
			local panel = Library:Create("Frame", {
				Name = "ModuleSettings_" .. tostring(Idx),
				BackgroundColor3 = Library.BackgroundColor,
				BorderColor3 = Library.AccentColor,
				BorderSizePixel = 1,
				Position = UDim2.fromOffset(Mouse.X + 8, Mouse.Y + 8),
				Size = UDim2.fromOffset(260, panelHeight),
				ZIndex = 200,
				Parent = Library.ScreenGui,
			})
			Toggle.SettingsPanel = panel
			Library:Create("TextLabel", {
				BackgroundColor3 = Library.MainColor,
				BorderSizePixel = 0,
				FontFace = Library.Font,
				Position = UDim2.fromOffset(1, 1),
				Size = UDim2.new(1, -2, 0, 24),
				Text = Toggle.Name .. " settings",
				TextColor3 = Library.AccentColor,
				TextSize = 13,
				TextXAlignment = Enum.TextXAlignment.Left,
				ZIndex = 201,
				Parent = panel,
			})

			if #settings == 0 then
				Library:Create("TextLabel", {
					BackgroundTransparency = 1,
					FontFace = Library.Font,
					Position = UDim2.fromOffset(6, 29),
					Size = UDim2.new(1, -12, 0, rowHeight),
					Text = "No module settings in this group.",
					TextColor3 = Library.FontColor,
					TextSize = 11,
					TextXAlignment = Enum.TextXAlignment.Left,
					ZIndex = 201,
					Parent = panel,
				})
			else
				for index = 1, visibleCount do
					local setting = settings[index]
					Library:Create("TextLabel", {
						BackgroundTransparency = 1,
						FontFace = Library.Font,
						Position = UDim2.fromOffset(6, 27 + (index - 1) * rowHeight),
						Size = UDim2.new(1, -12, 0, rowHeight),
						Text = string.format("%s: %s", setting.Name, setting.Value),
						TextColor3 = Library.FontColor,
						TextSize = 11,
						TextTruncate = Enum.TextTruncate.AtEnd,
						TextXAlignment = Enum.TextXAlignment.Left,
						ZIndex = 201,
						Parent = panel,
					})
				end
				if #settings > visibleCount then
					Library:Create("TextLabel", {
						BackgroundTransparency = 1,
						FontFace = Library.Font,
						Position = UDim2.fromOffset(6, 27 + visibleCount * rowHeight),
						Size = UDim2.new(1, -12, 0, rowHeight),
						Text = string.format("+ %d more; use the controls in this group.", #settings - visibleCount),
						TextColor3 = Library.FontColor,
						TextSize = 10,
						TextTruncate = Enum.TextTruncate.AtEnd,
						TextXAlignment = Enum.TextXAlignment.Left,
						ZIndex = 201,
						Parent = panel,
					})
				end
			end

			local closeConnection
			closeConnection = InputService.InputBegan:Connect(function(closeInput)
				if closeInput.UserInputType ~= Enum.UserInputType.MouseButton1
					and closeInput.UserInputType ~= Enum.UserInputType.MouseButton2 then
					return
				end
				if panel.Parent then
					panel:Destroy()
				end
				if closeConnection then
					closeConnection:Disconnect()
					closeConnection = nil
				end
				Toggle.SettingsPanel = nil
			end)
			panel.Destroying:Connect(function()
				if closeConnection then
					closeConnection:Disconnect()
					closeConnection = nil
				end
				if Toggle.SettingsPanel == panel then
					Toggle.SettingsPanel = nil
				end
			end)
		end

		function Toggle:OnChanged(Func)
			Toggle.Changed = Func;
			pcall(Func,Toggle.Value);
		end;

		function Toggle:SetValue(Bool)
			Bool = (not not Bool);

			Toggle.Value = Bool;
			Toggle:Display();

			for _, Addon in next, Toggle.Addons do
				if Addon.Type == 'KeyPicker' and Addon.SyncToggleState then
					Addon.Toggled = Bool
					Addon:Update()
				end
			end
			pcall(function()
				Library:SafeCallback(Toggle.Callback, Toggle.Value);
				Library:SafeCallback(Toggle.Changed, Toggle.Value);

				aztup_options.OnlyShowEnabledKeybinds.__internal:fire()
			end)
			Toggle.__internal:fire(Toggle.Value)
			Library.ToggleChanged:Fire(Toggle.Value)
			Library:UpdateDependencyBoxes();
		end;

		ToggleRegion.InputBegan:Connect(function(Input)
			if Input.UserInputType == Enum.UserInputType.MouseButton1 and not Library:MouseIsOverOpenedFrame() then
				Toggle:SetValue(not Toggle.Value)
				Library:AttemptSave();
			elseif Input.UserInputType == Enum.UserInputType.MouseButton2 then
				showModuleSettings(Input)
			end;
		end);
		ToggleLabel.InputBegan:Connect(showModuleSettings)

		if Toggle.Risky then
			Library:RemoveFromRegistry(ToggleLabel)
			ToggleLabel.TextColor3 = Library.RiskColor
			Library:AddToRegistry(ToggleLabel, { TextColor3 = 'RiskColor' })
		end

		Toggle:Display();
		if type(Info.Text) == 'string' and Info.Text ~= '' then
			Library:RegisterSearchEntry(Groupbox, {
				Kind = 'Toggle';
				Text = Info.Text;
				Tab = Groupbox.Tab or Groupbox;
				Target = ToggleOuter;
				Focus = function()
					Library:FocusSearchTarget(ToggleOuter)
				end;
			})
		end
		Groupbox:AddBlank(Info.BlankSize or 5 + 2);
		Groupbox:Resize();

		Toggle.TextLabel = ToggleLabel;
		Toggle.Container = Container;
		setmetatable(Toggle, BaseAddons or {})

		aztup_toggles[Idx] = Toggle;

		Library:UpdateDependencyBoxes();

		return Toggle	
end

	function Component.AddKeyPicker(self, Idx, Info)
		local ParentObj = self;
		local ToggleLabel = self.TextLabel;
		local Container = self.Container;
		
		
		

		assert(Info.Default, 'AddKeyPicker: Missing default value.');

		local KeyPicker = {
			Value = Info.Default;
			Toggled = false;
			Mode = Info.Mode or 'Toggle'; 
			Type = 'KeyPicker';
			Callback = Info.Callback or function(Value) end;
			ChangedCallback = Info.ChangedCallback or function(New) end;

			SyncToggleState = Info.SyncToggleState or false;
		};

		local Modes = Info.Modes or { 'Toggle', 'Hold' };

		self.KeyPicker = {
			Flag = Idx;
			Value = KeyPicker.Value
		}

		if not table.find(Modes, KeyPicker.Mode) then
			KeyPicker.Mode = Modes[1]
		end

		local ContainerLabelTransparencyTween
		local ContainerStrokeTransparencyTween

		local PickOuter = Library:Create('Frame', {
			BackgroundColor3 = Color3.new(0, 0, 0);
			BorderColor3 = Color3.new(0, 0, 0);
			Size = UDim2.new(0, 28, 0, 15);
			ZIndex = 6;
			Parent = ToggleLabel;
		});

		local PickInner = Library:Create('Frame', {
			BackgroundColor3 = Library.BackgroundColor;
			BorderColor3 = Library.OutlineColor;
			BorderMode = Enum.BorderMode.Inset;
			Size = UDim2.new(1, 0, 1, 0);
			ZIndex = 7;
			Parent = PickOuter;
		});

		Library:AddToRegistry(PickInner, {
			BackgroundColor3 = 'BackgroundColor';
			BorderColor3 = 'OutlineColor';
		});

		local DisplayLabel = Library:CreateLabel({
			Size = UDim2.new(1, 0, 1, 0);
			TextSize = 13;
			Text = Info.Default;
			TextWrapped = true;
			ZIndex = 8;
			Parent = PickInner;
			Name = "DisplayLabelKeybind";
		});

		local ModeSelectOuter = Library:Create('Frame', {
			BorderColor3 = Color3.new(0, 0, 0);
			Position = UDim2.fromOffset(ToggleLabel.AbsolutePosition.X + ToggleLabel.AbsoluteSize.X + 4, ToggleLabel.AbsolutePosition.Y + 1);
			Size = UDim2.new(0, 60, 0, (((#Modes)+1) * 15) + 2);
			Visible = false;
			ZIndex = 14;
			Parent = Library.ScreenGui;
		});

		Library:AddUIScale(ModeSelectOuter);

		ToggleLabel:GetPropertyChangedSignal('AbsolutePosition'):Connect(function()
			ModeSelectOuter.Position = UDim2.fromOffset(ToggleLabel.AbsolutePosition.X + ToggleLabel.AbsoluteSize.X + 4, ToggleLabel.AbsolutePosition.Y + 1);
